Here is the commit message:
net: mvpp2: limit XDP frame size to the RX buffer

mvpp2 has short and long BM pools, and short pool buffers can be smaller
than PAGE_SIZE. The XDP path nevertheless initializes every xdp_buff with
PAGE_SIZE as frame size.

XDP helpers use frame_sz to validate tail growth and to derive the hard
end of the data area. Advertising PAGE_SIZE for short buffers can let
bpf_xdp_adjust_tail() grow a packet past the real allocation, corrupting
memory or later tripping skb tailroom checks.

Initialize the XDP buffer with bm_pool->frag_size so XDP tailroom matches
the actual buffer backing the packet.

Fixes: 07dd0a7aae7f ("mvpp2: add basic XDP support")
Signed-off-by: Til Kaiser <mail@tk154.de>
Link: https://patch.msgid.link/20260607134943.21996-3-mail@tk154.de
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
The XDP buffer was initialized with a frame size of `PAGE_SIZE` regardless of the actual buffer pool size, allowing `bpf_xdp_adjust_tail()` to grow packets beyond the real buffer allocation, leading to memory corruption when using short buffer pools with smaller `frag_size`.

Here is the patch:
 /* Main rx processing */
 static int mvpp2_rx(struct mvpp2_port *port, struct napi_struct *napi,
 		    int rx_todo, struct mvpp2_rx_queue *rxq)
 {
 	struct net_device *dev = port->dev;
 	struct mvpp2_pcpu_stats ps = {};
 	enum dma_data_direction dma_dir;
 	struct bpf_prog *xdp_prog;
 	struct xdp_buff xdp;
 	int rx_received;
 	int rx_done = 0;
 	u32 xdp_ret = 0;

 	xdp_prog = READ_ONCE(port->xdp_prog);

 	/* Get number of received packets and clamp the to-do */
 	rx_received = mvpp2_rxq_received(port, rxq->id);
 	if (rx_todo > rx_received)
 		rx_todo = rx_received;

 	while (rx_done < rx_todo) {
 		struct mvpp2_rx_desc *rx_desc = mvpp2_rxq_next_desc_get(rxq);
 		u32 rx_status, timestamp, metasize = 0;
 		struct mvpp2_bm_pool *bm_pool;
 		struct page_pool *pp = NULL;
 		struct sk_buff *skb;
 		unsigned int frag_size;
 		dma_addr_t dma_addr;
 		phys_addr_t phys_addr;
 		int pool, rx_bytes, err, ret;
 		struct page *page;
 		void *data;

 		phys_addr = mvpp2_rxdesc_cookie_get(port, rx_desc);
 		data = (void *)phys_to_virt(phys_addr);
 		page = virt_to_page(data);
 		prefetch(page);

 		rx_done++;
 		rx_status = mvpp2_rxdesc_status_get(port, rx_desc);
 		rx_bytes = mvpp2_rxdesc_size_get(port, rx_desc);
 		rx_bytes -= MVPP2_MH_SIZE;
 		dma_addr = mvpp2_rxdesc_dma_addr_get(port, rx_desc);

 		pool = (rx_status & MVPP2_RXD_BM_POOL_ID_MASK) >>
 			MVPP2_RXD_BM_POOL_ID_OFFS;
 		bm_pool = &port->priv->bm_pools[pool];

 		if (port->priv->percpu_pools) {
 			pp = port->priv->page_pool[pool];
 			dma_dir = page_pool_get_dma_dir(pp);
 		} else {
 			dma_dir = DMA_FROM_DEVICE;
 		}

 		dma_sync_single_range_for_cpu(dev->dev.parent, dma_addr,
 					      MVPP2_SKB_HEADROOM,
 					      rx_bytes + MVPP2_MH_SIZE,
 					      dma_dir);

 		/* Buffer header not supported */
 		if (rx_status & MVPP2_RXD_BUF_HDR)
 			goto err_drop_frame;

 		/* In case of an error, release the requested buffer pointer
 		 * to the Buffer Manager. This request process is controlled
 		 * by the hardware, and the information about the buffer is
 		 * comprised by the RX descriptor.
 		 */
 		if (rx_status & MVPP2_RXD_ERR_SUMMARY)
 			goto err_drop_frame;

 		/* Prefetch header */
 		prefetch(data + MVPP2_MH_SIZE + MVPP2_SKB_HEADROOM);

 		if (bm_pool->frag_size > PAGE_SIZE)
 			frag_size = 0;
 		else
 			frag_size = bm_pool->frag_size;

 		if (xdp_prog) {
 			struct xdp_rxq_info *xdp_rxq;

 			if (bm_pool->pkt_size == MVPP2_BM_SHORT_PKT_SIZE)
 				xdp_rxq = &rxq->xdp_rxq_short;
 			else
 				xdp_rxq = &rxq->xdp_rxq_long;

-			xdp_init_buff(&xdp, PAGE_SIZE, xdp_rxq);
+			xdp_init_buff(&xdp, bm_pool->frag_size, xdp_rxq);
 			xdp_prepare_buff(&xdp, data,
 					 MVPP2_MH_SIZE + MVPP2_SKB_HEADROOM,
 					 rx_bytes, true);

 			ret = mvpp2_run_xdp(port, xdp_prog, &xdp, pp, &ps);

 			if (ret) {
 				xdp_ret |= ret;
 				err = mvpp2_rx_refill(port, bm_pool, pp, pool);
 				if (err) {
 					netdev_err(port->dev, "failed to refill BM pools\n");
 					goto err_drop_frame;
 				}

 				ps.rx_packets++;
 				ps.rx_bytes += rx_bytes;
 				continue;
 			}

 			metasize = xdp.data - xdp.data_meta;
 		}

 		if (frag_size)
 			skb = build_skb(data, frag_size);
 		else
 			skb = slab_build_skb(data);
 		if (!skb) {
 			netdev_warn(port->dev, "skb build failed\n");
 			goto err_drop_frame;
 		}

 		/* If we have RX hardware timestamping enabled, grab the
 		 * timestamp from the queue and convert.
 		 */
 		if (mvpp22_rx_hwtstamping(port)) {
 			timestamp = le32_to_cpu(rx_desc->pp22.timestamp);
 			mvpp22_tai_tstamp(port->priv->tai, timestamp,
 					 skb_hwtstamps(skb));
 		}

 		err = mvpp2_rx_refill(port, bm_pool, pp, pool);
 		if (err) {
 			netdev_err(port->dev, "failed to refill BM pools\n");
 			dev_kfree_skb_any(skb);
 			goto err_drop_frame;
 		}

 		if (pp)
 			skb_mark_for_recycle(skb);
 		else
 			dma_unmap_single_attrs(dev->dev.parent, dma_addr,
 					       bm_pool->buf_size, DMA_FROM_DEVICE,
 					       DMA_ATTR_SKIP_CPU_SYNC);

 		ps.rx_packets++;
 		ps.rx_bytes += rx_bytes;

 		skb_reserve(skb, MVPP2_MH_SIZE + MVPP2_SKB_HEADROOM);
 		skb_put(skb, rx_bytes);
 		if (metasize)
 			skb_metadata_set(skb, metasize);
 		skb->ip_summed = mvpp2_rx_csum(port, rx_status);
 		skb->protocol = eth_type_trans(skb, dev);

 		napi_gro_receive(napi, skb);
 		continue;

 err_drop_frame:
 		dev->stats.rx_errors++;
 		mvpp2_rx_error(port, rx_desc);
 		/* Return the buffer to the pool */
 		if (rx_status & MVPP2_RXD_BUF_HDR)
 			mvpp2_buff_hdr_pool_put(port, rx_desc, pool, rx_status);
 		else
 			mvpp2_bm_pool_put(port, pool, dma_addr, phys_addr);
 	}

 	if (xdp_ret & MVPP2_XDP_REDIR)
 		xdp_do_flush();

 	if (ps.rx_packets) {
 		struct mvpp2_pcpu_stats *stats = this_cpu_ptr(port->stats);

 		u64_stats_update_begin(&stats->syncp);
 		stats->rx_packets += ps.rx_packets;
 		stats->rx_bytes   += ps.rx_bytes;
 		/* xdp */
 		stats->xdp_redirect += ps.xdp_redirect;
 		stats->xdp_pass += ps.xdp_pass;
 		stats->xdp_drop += ps.xdp_drop;
 		u64_stats_update_end(&stats->syncp);
 	}

 	/* Update Rx queue management counters */
 	wmb();
 	mvpp2_rxq_status_update(port, rxq->id, rx_done, rx_done);

 	return rx_todo;
 }



